static __m128i gfpow(__m128i h,uint64_t e){ /* h^e, e>=0; one = 0x80..0 in reflected? use loop */
  __m128i r; int have=0;
  while(e){ if(e&1){ r= have? gfmul(r,h):h; have=1;} h=gfmul(h,h); e>>=1; }
  if(!have){ /* multiplicative identity in this (bswapped) domain */
    r=_mm_set_epi64x(0,1); }
  return r;
}
/* ghash over nb full blocks starting from x, H powers hp[0..3]=H^1..H^4 (bswapped) */
static __m128i ghash_blocks(__m128i x,const uint8_t*p,size_t nb,const __m128i*hp){
  size_t i=0;
  for(;i+4<=nb;i+=4){
    __m128i c0=_mm_xor_si128(x,bswap(_mm_loadu_si128((const __m128i*)(p+16*i))));
    __m128i c1=bswap(_mm_loadu_si128((const __m128i*)(p+16*i+16)));
    __m128i c2=bswap(_mm_loadu_si128((const __m128i*)(p+16*i+32)));
    __m128i c3=bswap(_mm_loadu_si128((const __m128i*)(p+16*i+48)));
    __m128i lo=_mm_setzero_si128(),mid=lo,hi=lo;
    mul_acc(c0,hp[3],&lo,&mid,&hi); mul_acc(c1,hp[2],&lo,&mid,&hi);
    mul_acc(c2,hp[1],&lo,&mid,&hi); mul_acc(c3,hp[0],&lo,&mid,&hi);
    x=reduce(lo,mid,hi);
  }
  for(;i<nb;i++){ x=gfmul(_mm_xor_si128(x,bswap(_mm_loadu_si128((const __m128i*)(p+16*i)))),hp[0]); }
  return x;
}
static __m128i ghash_bytes(__m128i x,const uint8_t*p,size_t n,const __m128i*hp){
  size_t nb=n/16; x=ghash_blocks(x,p,nb,hp);
  if(n%16){ uint8_t b[16]={0}; memcpy(b,p+16*nb,n%16); x=ghash_blocks(x,b,1,hp); }
  return x;
}
