  EVP_EncryptInit_ex(c,ctr_cipher(j->klen),NULL,j->key,j->ctr);
  __m128i x=_mm_setzero_si128();
  const size_t CH=32768; size_t done=0;
  while(done<j->len){
    size_t n=j->len-done; if(n>CH)n=CH;
    int ol; EVP_EncryptUpdate(c,j->out+j->off+done,&ol,j->in+j->off+done,(int)n);
    x=ghash_bytes(x,j->out+j->off+done,n,j->hp);
    done+=n;
  }
  EVP_CIPHER_CTX_free(c);
  j->res=x; return NULL;
}
static void add_ctr(uint8_t*c,uint64_t v){ /* 128-bit BE add */
  for(int i=15;i>=0&&v;i--){ uint64_t s=c[i]+(v&0xff); c[i]=(uint8_t)s; v=(v>>8)+(s>>8);} 
}
/* nonce 12 bytes. returns 0 ok */
int gcm_encrypt(const uint8_t*key,int klen,const uint8_t*nonce,const uint8_t*aad,size_t alen,
                const uint8_t*in,size_t n,uint8_t*out,uint8_t*tag,int nthreads){
  uint8_t zero[16]={0},Hb[16],J0[16],EJ0[16];int ol;
  EVP_CIPHER_CTX*c=EVP_CIPHER_CTX_new();
  EVP_EncryptInit_ex(c,ctr_cipher(klen),NULL,key,zero); EVP_EncryptUpdate(c,Hb,&ol,zero,16);
  memcpy(J0,nonce,12); J0[12]=0;J0[13]=0;J0[14]=0;J0[15]=1;
  EVP_EncryptInit_ex(c,NULL,NULL,NULL,J0); EVP_EncryptUpdate(c,EJ0,&ol,zero,16);
  EVP_CIPHER_CTX_free(c);
  __m128i hp[4]; hp[0]=bswap(_mm_loadu_si128((__m128i*)Hb));
  /* Intel algorithm requires H shifted? The white-paper gfmul works on reflected-bitswapped inputs directly */
  hp[1]=gfmul(hp[0],hp[0]); hp[2]=gfmul(hp[1],hp[0]); hp[3]=gfmul(hp[2],hp[0]);
  uint64_t totb=(n+15)/16;
  if(nthreads<1)nthreads=1;
  if(n<(1<<20))nthreads=1;
  job_t jobs[64]; pthread_t th[64];
  uint64_t per=(totb+nthreads-1)/nthreads; 
  int nj=0;
  for(int t=0;t<nthreads;t++){
    uint64_t b0=per*t; if(b0>=totb)break;
    uint64_t b1=b0+per; if(b1>totb)b1=totb;
    job_t*j=&jobs[nj++]; j->key=key;j->klen=klen;j->in=in;j->out=out;j->hp=hp;
    j->off=b0*16; size_t e=b1*16; if(e>n)e=n; j->len=e-j->off;
    memcpy(j->ctr,J0,16); add_ctr(j->ctr,1+b0);
  }
  for(int t=1;t<nj;t++) pthread_create(&th[t],NULL,worker,&jobs[t]);
  if(nj>0) worker(&jobs[0]);
  for(int t=1;t<nj;t++) pthread_join(th[t],NULL);
  __m128i x=ghash_bytes(_mm_setzero_si128(),aad,alen,hp);
  x=gfmul(x,gfpow(hp[0],totb)); /* fine even if totb==0 handled below */
  if(totb==0) x=ghash_bytes(_mm_setzero_si128(),aad,alen,hp);
  for(int t=0;t<nj;t++){
    uint64_t b1=(t==nj-1)?totb:per*(t+1);
    __m128i y=jobs[t].res;
    if(b1<totb) y=gfmul(y,gfpow(hp[0],totb-b1));
    x=_mm_xor_si128(x,y);
  }
