  for(int i=0;i<8;i++){L[i]=(uint8_t)(ab>>(56-8*i));L[8+i]=(uint8_t)(cb>>(56-8*i));}
  x=ghash_blocks(x,L,1,hp);
  __m128i t=_mm_xor_si128(bswap(x),_mm_loadu_si128((__m128i*)EJ0));
  _mm_storeu_si128((__m128i*)tag,t);
  return 0;
}
